-- HotelCare production schema baseline for the NTAK acceptance gate (review item 12).
-- Provenance: generated by Claude on 2026-11-24 05:40 Europe/Budapest from Supabase project
-- pcmszqqklkolvvlabohq using pg_catalog (pg_attribute, pg_attrdef, pg_constraint, pg_index).
-- Schema only. No rows, credentials, certificates, keys or endpoint values. Column defaults that
-- contained a URL were omitted.
--
-- SCOPE (read before relying on this file):
--   * Exact columns, types, NOT NULL, defaults, CHECK / PRIMARY KEY / UNIQUE / EXCLUSION
--     constraints, foreign keys and indexes of the 32 public tables listed below.
--   * NOT included: functions, triggers, RLS policies, grants, views. Production has several
--     hundred functions; they cannot be exported through the tool Claude has. The helper
--     functions the NTAK migrations call are created here as minimal STUBS (clearly marked);
--     regression tests that need real behaviour must create their own versions.
--   * auth.users, auth.uid() and public.venues are stubs so foreign keys resolve.
--
-- Deployed migration inventory (supabase_migrations.schema_migrations, NTAK-relevant tail):
--   viza_checkin_trigger_fix, ntak_phase1_validation_scope, pms_financial_core_phase1_tables,
--   pms_financial_core_phase1_functions, ntak_phase2_business_moment (2 parts),
--   ntak_phase3_guest_schema, ntak_phase3_guest_lifecycle (3 parts), ntak_phase3_finance_guard,
--   ntak_phase3_activation_safety, ntak_phase10_evidence, training_release_approval,
--   ntak_authority_guest_rls, authority_settings_roles, ntak_phase6_booking_fields,
--   ntak_phase5_walk_in_sales, ntak_phase9_message_recovery,
--   ntak_phase4_room_state_periods_with_review_fix (Phase 4 + 20261124010000 in one step).
--   NOT deployed: 20261123235900_ntak_phase8_catalogue_categories.sql (held: NULL organisation bug).

CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role NOLOGIN BYPASSRLS; END IF;
END $$;

-- STUBS -------------------------------------------------------------------------------------
CREATE SCHEMA IF NOT EXISTS auth;
CREATE TABLE IF NOT EXISTS auth.users (id uuid PRIMARY KEY);
-- STUB: tests set the caller with  SELECT set_config('request.jwt.claim.sub', '<uuid>', true);
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
CREATE TABLE IF NOT EXISTS public.venues (id uuid PRIMARY KEY DEFAULT gen_random_uuid());
-- STUB of the production default helper for organization_slug columns.
CREATE OR REPLACE FUNCTION public.pi_user_org() RETURNS text LANGUAGE sql STABLE AS $$ SELECT NULL::text $$;

-- ENUMS (exact production labels and order) ----------------------------------------------------
CREATE TYPE public.reservation_status AS ENUM ('pending','confirmed','checked_in','checked_out','cancelled','no_show');
CREATE TYPE public.user_role AS ENUM ('housekeeping','reception','maintenance','manager','admin','marketing','control_finance','hr','front_office','top_management','housekeeping_manager','maintenance_manager','marketing_manager','reception_manager','back_office_manager','control_manager','finance_manager','top_management_manager','breakfast_staff','back_office','supervisor');

SET search_path = public;

