-- CHECK constraints ------------------------------------------------------------------------
-- Two long list constraints are deployed but not repeated here; their exact text is in the
-- migrations: pos_sale_line_other_category (20261123230000) and
-- reservations_booker_country_check (20261123223000).
ALTER TABLE public.folio_lines ADD CONSTRAINT folio_lines_quantity_check CHECK ((quantity > (0)::numeric));
ALTER TABLE public.folio_lines ADD CONSTRAINT folio_lines_status_check CHECK ((status = ANY (ARRAY['open'::text, 'invoiced'::text, 'reversed'::text, 'voided'::text])));
ALTER TABLE public.folio_lines ADD CONSTRAINT folio_lines_vat_rate_check CHECK (((vat_rate IS NULL) OR ((vat_rate >= (0)::numeric) AND (vat_rate <= (100)::numeric))));
ALTER TABLE public.guests ADD CONSTRAINT guests_gender_check CHECK (((gender IS NULL) OR (gender = ANY (ARRAY['male'::text, 'female'::text, 'other'::text]))));
ALTER TABLE public.ntak_daily_closures ADD CONSTRAINT ntak_daily_closures_classification_check CHECK ((classification = ANY (ARRAY['UJ'::text, 'MODOSITO'::text])));
ALTER TABLE public.ntak_daily_closures ADD CONSTRAINT ntak_daily_closures_override_reason_check CHECK (((override_reason IS NULL) OR ((length(btrim(override_reason)) >= 1) AND (length(btrim(override_reason)) <= 500))));
