-- UNIQUE INDEXES that are not constraints (they change behaviour: ON CONFLICT targets and
-- duplicate protection). Plain performance indexes are not reproduced.
CREATE UNIQUE INDEX ntak_evidence_send_once ON public.ntak_message_evidence USING btree (uzenet_id) WHERE (phase = 'send'::text);
CREATE UNIQUE INDEX ntak_evidence_verify_once ON public.ntak_message_evidence USING btree (uzenet_id, query_id) WHERE (phase = 'verify'::text);
CREATE UNIQUE INDEX ntak_messages_uzenet ON public.ntak_messages USING btree (uzenet_id) WHERE (uzenet_id IS NOT NULL);
CREATE UNIQUE INDEX profiles_nickname_org_unique ON public.profiles USING btree (lower(nickname), organization_slug) WHERE (nickname IS NOT NULL);
CREATE UNIQUE INDEX reservation_folios_one_master_idx ON public.reservation_folios USING btree (reservation_id) WHERE ((folio_type = 'master'::text) AND (parent_folio_id IS NULL));
CREATE UNIQUE INDEX reservations_channex_booking_room_uidx ON public.reservations USING btree (channex_booking_id, channex_room_index) WHERE (channex_booking_id IS NOT NULL);
CREATE UNIQUE INDEX uq_reservations_hotel_source_ref ON public.reservations USING btree (hotel_id, source, source_reservation_id);
CREATE UNIQUE INDEX viza_guest_events_res_guest ON public.viza_guest_events USING btree (reservation_id, COALESCE(guest_id, '00000000-0000-0000-0000-000000000000'::uuid));
CREATE UNIQUE INDEX viza_trigger_failures_open_transition ON public.viza_trigger_failures USING btree (reservation_id, from_status, to_status) WHERE (resolved_at IS NULL);

-- DATA FACTS the regression suite should reproduce with synthetic rows (no production rows here):
--   * 6,147 of 17,108 reservations have organization_slug IS NULL (older Previo-synced rows).
--   * rooms.hotel holds the hotel DISPLAY NAME, not the hotel id.
--   * rooms.status is one of clean / dirty / out_of_order / maintenance (CHECK above).
--   * profiles.role is the user_role enum; compare as text.
--
-- Signatures of deployed helper functions the NTAK migrations call (bodies NOT included; write
-- test doubles with these exact signatures):
--   has_pms_access(user_id uuid) -> boolean
--   can_access_pms_hotel(_uid uuid, _hotel_id text, _org_slug text) -> boolean
--   can_access_reservation(_uid uuid, _reservation_id uuid) -> boolean
--   user_can_access_hotel(_uid uuid, _hotel_id text) -> boolean
--   get_user_role(user_id uuid) -> user_role
--   get_user_organization_slug(user_id uuid) -> text
--   is_super_admin(user_id uuid) -> boolean
--   pms_hotel_room_keys(_hotel_id text) -> setof text
--   pms_recalc_reservation_financials(_reservation_id uuid) -> void
--   pms_check_in_reservation(_reservation_id uuid, _room_id uuid, _override boolean) -> jsonb
